import { SF_CONFIG } from "../config";

export default function Login() {
  const handleLogin = () => {
    const url = `${SF_CONFIG.loginUrl}/services/oauth2/authorize?response_type=code&client_id=${SF_CONFIG.clientId}&redirect_uri=${encodeURIComponent(SF_CONFIG.redirectUri)}&scope=full%20refresh_token%20offline_access`;

    window.location.assign(url);
  };

  return (
    <div>
      <p>Connect your Salesforce Org to manage Validation Rules</p>
      <button onClick={handleLogin}>
        Login to Salesforce
      </button>
    </div>
  );
}
